document.addEventListener("DOMContentLoaded",function(){const e=document.getElementById("tool-search");if(!e)return;const n=document.querySelectorAll(".tools-grid .tool-card"),t=document.getElementById("tool-search-empty");e.addEventListener("input",function(e){const s=e.target.value.toLowerCase();let o=0;n.forEach(function(e){const n=e.querySelector(".tool-title").textContent.toLowerCase(),i=e.querySelector(".tool-desc").textContent.toLowerCase(),t=n.includes(s)||i.includes(s);e.style.display=t?"":"none",t&&(o+=1)}),t&&(t.hidden=o>0)})})